findings.codeql_raw_query:
/**
 * @name Tainted eval in typing_extensions
 * @description Check if eval calls receive tainted input
 * @kind path-problem
 * @problem.severity error
 * @id py/tainted-eval-typing-extensions
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module TaintedEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters
    source instanceof DataFlow::ParameterNode
    or
    // Class attributes
    exists(DataFlow::AttrRead attr | source = attr)
    or
    // Any external call result
    exists(DataFlow::CallCfgNode call | source = call)
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = "eval" or
      call = API::builtin("eval").getACall() |
      sink = call.getArg(0)
    )
  }
}

module TaintedEvalFlow = TaintTracking::Global<TaintedEvalConfig>;
import TaintedEvalFlow::PathGraph

from TaintedEvalFlow::PathNode source, TaintedEvalFlow::PathNode sink
where 
  TaintedEvalFlow::flowPath(source, sink) and
  sink.getNode().getLocation().getFile().getBaseName() = "typing_extensions.py"
select sink.getNode(), source, sink, "eval() receives potentially tainted input from $@.", source.getNode(), "this source"
